import{_ as t,c as a,o,a0 as i}from"./chunks/framework.oTSD2LDJ.js";const c=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ","layout":"doc","editLink":true},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),n={name:"en/faq.md"};function s(l,e,r,h,d,p){return o(),a("div",null,e[0]||(e[0]=[i(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><p>Here are the most common issues users encounter when using Uniquenium. If you don&#39;t find an answer, feel free to submit an Issue on GitHub.</p><h2 id="installation-startup" tabindex="-1">Installation &amp; Startup <a class="header-anchor" href="#installation-startup" aria-label="Permalink to &quot;Installation &amp; Startup&quot;">​</a></h2><h3 id="q-getting-qt6-not-found-or-cmake-errors-during-compilation" tabindex="-1">Q: Getting &quot;Qt6 not found&quot; or CMake errors during compilation <a class="header-anchor" href="#q-getting-qt6-not-found-or-cmake-errors-during-compilation" aria-label="Permalink to &quot;Q: Getting &quot;Qt6 not found&quot; or CMake errors during compilation&quot;">​</a></h3><p><strong>A:</strong> Please ensure:</p><ol><li>Qt 6.5.0+ is installed correctly with required modules (Core, Widgets, Quick, QuickControls2, DBus, Core5Compat, LabsPlatform, Concurrent)</li><li>The Qt path is correctly specified when configuring CMake:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_PREFIX_PATH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:/Qt/6.8.3/msvc2022_64&quot;</span></span></code></pre></div></li><li>ECM (Extra CMake Modules) is installed</li></ol><h3 id="q-program-flashes-and-exits-no-window-shown" tabindex="-1">Q: Program flashes and exits, no window shown <a class="header-anchor" href="#q-program-flashes-and-exits-no-window-shown" aria-label="Permalink to &quot;Q: Program flashes and exits, no window shown&quot;">​</a></h3><p><strong>A:</strong> Try the following steps:</p><ol><li>Check the tray area (bottom-right taskbar) for the Uniquenium icon; the program minimizes to the tray by default</li><li>If no tray icon, launch from the command line to view error messages:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Uniquenium0.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --debug</span></span></code></pre></div></li><li>Ensure your graphics driver is updated to the latest version</li><li>Try running in software rendering mode (lower performance):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QMLSCENE_DEVICE=softwarecontext</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Uniquenium0.exe</span></span></code></pre></div></li></ol><h3 id="q-installer-blocked-by-windows-defender-smartscreen" tabindex="-1">Q: Installer blocked by Windows Defender / SmartScreen <a class="header-anchor" href="#q-installer-blocked-by-windows-defender-smartscreen" aria-label="Permalink to &quot;Q: Installer blocked by Windows Defender / SmartScreen&quot;">​</a></h3><p><strong>A:</strong> This is normal since the program doesn&#39;t have a code signing certificate. Please:</p><ol><li>Click &quot;More info&quot; → &quot;Run anyway&quot;</li><li>Or right-click the installer → Properties → Check &quot;Unblock&quot; → OK</li></ol><h3 id="q-wallpaper-feature-not-working-on-older-windows-10" tabindex="-1">Q: Wallpaper feature not working on older Windows 10 <a class="header-anchor" href="#q-wallpaper-feature-not-working-on-older-windows-10" aria-label="Permalink to &quot;Q: Wallpaper feature not working on older Windows 10&quot;">​</a></h3><p><strong>A:</strong> Some older Windows 10 versions (before 1809) have compatibility issues with the wallpaper API. It is recommended to upgrade to Windows 10 21H2 or Windows 11.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="q-how-do-i-add-components-to-the-desktop" tabindex="-1">Q: How do I add components to the desktop? <a class="header-anchor" href="#q-how-do-i-add-components-to-the-desktop" aria-label="Permalink to &quot;Q: How do I add components to the desktop?&quot;">​</a></h3><p><strong>A:</strong> Steps:</p><ol><li>Open the main panel (default shortcut: <code>Ctrl + Alt + U</code>)</li><li>Click &quot;+ New Page&quot; on the left side or select an existing page</li><li>Click the &quot;Add Component&quot; button</li><li>Select the component type from the component list</li><li>Drag to adjust the component&#39;s position and size</li></ol><h3 id="q-how-do-i-delete-a-component" tabindex="-1">Q: How do I delete a component? <a class="header-anchor" href="#q-how-do-i-delete-a-component" aria-label="Permalink to &quot;Q: How do I delete a component?&quot;">​</a></h3><p><strong>A:</strong> Three ways:</p><ol><li>Select the component and press <code>Delete</code></li><li>Right-click the component → select &quot;Delete&quot;</li><li>Right-click in the component tree of the page management window → &quot;Delete&quot;</li></ol><h3 id="q-component-dragged-off-screen-and-can-t-be-found" tabindex="-1">Q: Component dragged off-screen and can&#39;t be found? <a class="header-anchor" href="#q-component-dragged-off-screen-and-can-t-be-found" aria-label="Permalink to &quot;Q: Component dragged off-screen and can&#39;t be found?&quot;">​</a></h3><p><strong>A:</strong> Open the page management window (Settings → Page Management), select the component in the component tree, and reset X/Y coordinates to 0 in the right property panel.</p><h3 id="q-how-do-i-adjust-the-component-layering-z-order" tabindex="-1">Q: How do I adjust the component layering (Z-order)? <a class="header-anchor" href="#q-how-do-i-adjust-the-component-layering-z-order" aria-label="Permalink to &quot;Q: How do I adjust the component layering (Z-order)?&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>Select the component</li><li>Right-click → select &quot;Move Up&quot; / &quot;Move Down&quot; / &quot;Bring to Front&quot; / &quot;Send to Back&quot;</li><li>Or drag directly in the component tree to adjust order</li></ol><h2 id="theme-appearance" tabindex="-1">Theme &amp; Appearance <a class="header-anchor" href="#theme-appearance" aria-label="Permalink to &quot;Theme &amp; Appearance&quot;">​</a></h2><h3 id="q-how-do-i-switch-between-dark-light-themes" tabindex="-1">Q: How do I switch between dark/light themes? <a class="header-anchor" href="#q-how-do-i-switch-between-dark-light-themes" aria-label="Permalink to &quot;Q: How do I switch between dark/light themes?&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>Right-click the tray icon → Settings → Appearance</li><li>Select theme mode: Follow System / Light / Dark</li><li>You can also use shortcuts to quickly switch (bind in settings first)</li></ol><h3 id="q-acrylic-blur-effect-not-showing" tabindex="-1">Q: Acrylic blur effect not showing <a class="header-anchor" href="#q-acrylic-blur-effect-not-showing" aria-label="Permalink to &quot;Q: Acrylic blur effect not showing&quot;">​</a></h3><p><strong>A:</strong> The acrylic effect depends on:</p><ul><li>Windows 10 1803+ or Windows 11</li><li>GPU supports hardware acceleration</li><li>Confirm &quot;Enable Acrylic Effect&quot; is enabled in Settings → Appearance</li></ul><p>If it still doesn&#39;t display, try updating your graphics driver.</p><h3 id="q-can-i-use-custom-wallpapers" tabindex="-1">Q: Can I use custom wallpapers? <a class="header-anchor" href="#q-can-i-use-custom-wallpapers" aria-label="Permalink to &quot;Q: Can I use custom wallpapers?&quot;">​</a></h3><p><strong>A:</strong> Yes! Supports:</p><ul><li>Local images (JPG/PNG/BMP/WebP)</li><li>Multiple image carousel</li><li>Custom API interfaces for fetching online wallpapers Path: Settings → Appearance → Wallpaper</li></ul><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><h3 id="q-global-shortcuts-not-working" tabindex="-1">Q: Global shortcuts not working <a class="header-anchor" href="#q-global-shortcuts-not-working" aria-label="Permalink to &quot;Q: Global shortcuts not working&quot;">​</a></h3><p><strong>A:</strong> Please check:</p><ol><li>Whether the shortcut conflicts with other software (QQ, WeChat, input methods, etc.)</li><li>Whether running with administrator privileges (some system hotkeys require admin rights)</li><li>Confirm the hotkey is enabled in Settings → Shortcuts</li><li>Try rebinding to a less commonly used key combination</li></ol><h3 id="q-how-to-modify-delete-shortcuts" tabindex="-1">Q: How to modify/delete shortcuts? <a class="header-anchor" href="#q-how-to-modify-delete-shortcuts" aria-label="Permalink to &quot;Q: How to modify/delete shortcuts?&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>Open Settings → Shortcuts</li><li>Find the function to modify</li><li>Click the shortcut input box and press the new key combination</li><li>Click &quot;Apply&quot; to save</li><li>To delete, click the &quot;Clear&quot; button next to the input box</li></ol><h2 id="plugins-templates" tabindex="-1">Plugins &amp; Templates <a class="header-anchor" href="#plugins-templates" aria-label="Permalink to &quot;Plugins &amp; Templates&quot;">​</a></h2><h3 id="q-how-do-i-install-third-party-plugins" tabindex="-1">Q: How do I install third-party plugins? <a class="header-anchor" href="#q-how-do-i-install-third-party-plugins" aria-label="Permalink to &quot;Q: How do I install third-party plugins?&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>Download the plugin package (usually <code>.zip</code> or <code>.uniq-plugin</code>)</li><li>Open Settings → Plugins</li><li>Click the &quot;Install Plugin&quot; button and select the downloaded file</li><li>Or manually extract the plugin to:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%APPDATA%\\Uniquenium\\Plugins\\</span></span></code></pre></div></li><li>Restart the program</li></ol><h3 id="q-plugin-not-showing-not-working-after-installation" tabindex="-1">Q: Plugin not showing/not working after installation <a class="header-anchor" href="#q-plugin-not-showing-not-working-after-installation" aria-label="Permalink to &quot;Q: Plugin not showing/not working after installation&quot;">​</a></h3><p><strong>A:</strong> Please:</p><ol><li>Check if the plugin version matches the Uniquenium version</li><li>Check if the plugin is enabled in Settings → Plugins</li><li>Open the log window (Settings → About → View Logs) to check for error messages</li><li>Contact the plugin author or submit an Issue on GitHub</li></ol><h3 id="q-how-to-export-import-page-templates" tabindex="-1">Q: How to export/import page templates? <a class="header-anchor" href="#q-how-to-export-import-page-templates" aria-label="Permalink to &quot;Q: How to export/import page templates?&quot;">​</a></h3><p><strong>A:</strong></p><ol><li><strong>Export</strong>: Right-click on the page → Export as Template → Choose save location</li><li><strong>Import</strong>: When creating a new page, select &quot;Import from Template&quot; → Choose the template file</li><li>Template files include page layout and all component configurations, but not external image resources</li></ol><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="q-high-memory-usage" tabindex="-1">Q: High memory usage <a class="header-anchor" href="#q-high-memory-usage" aria-label="Permalink to &quot;Q: High memory usage&quot;">​</a></h3><p><strong>A:</strong> Suggestions:</p><ol><li>Reduce the number of simultaneously displayed components</li><li>Disable unnecessary plugins</li><li>Lower the wallpaper blur radius (Settings → Appearance → Blur Intensity)</li><li>Avoid using excessively large wallpaper images</li></ol><h3 id="q-lag-when-dragging-windows" tabindex="-1">Q: Lag when dragging windows <a class="header-anchor" href="#q-lag-when-dragging-windows" aria-label="Permalink to &quot;Q: Lag when dragging windows&quot;">​</a></h3><p><strong>A:</strong> This is a known issue with Qt frameless windows. Try:</p><ol><li>Update graphics driver to the latest version</li><li>Close unnecessary background programs to free GPU resources</li><li>Disable &quot;Window Shadow&quot; and &quot;Acrylic Effect&quot; in settings</li></ol><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="q-how-to-get-program-logs" tabindex="-1">Q: How to get program logs? <a class="header-anchor" href="#q-how-to-get-program-logs" aria-label="Permalink to &quot;Q: How to get program logs?&quot;">​</a></h3><p><strong>A:</strong> Three ways:</p><ol><li>Add <code>--debug</code> parameter when launching from command line; logs output directly to console</li><li>Settings → About → Click &quot;View Logs&quot; button</li><li>Open the log file directly:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%APPDATA%\\Uniquenium\\Logs\\uniquenium-YYYY-MM-DD.log</span></span></code></pre></div></li></ol><h3 id="q-how-to-contribute-to-development-or-submit-code" tabindex="-1">Q: How to contribute to development or submit code? <a class="header-anchor" href="#q-how-to-contribute-to-development-or-submit-code" aria-label="Permalink to &quot;Q: How to contribute to development or submit code?&quot;">​</a></h3><p><strong>A:</strong> Contributions welcome! Please:</p><ol><li>Fork the project repository to your GitHub account</li><li>Create a new branch to develop features or fix bugs</li><li>Ensure code passes existing tests</li><li>Submit a Pull Request with detailed description of changes</li></ol><h3 id="q-the-feature-i-want-doesn-t-exist" tabindex="-1">Q: The feature I want doesn&#39;t exist? <a class="header-anchor" href="#q-the-feature-i-want-doesn-t-exist" aria-label="Permalink to &quot;Q: The feature I want doesn&#39;t exist?&quot;">​</a></h3><p><strong>A:</strong> You can:</p><ol><li>Check the <a href="https://github.com/Uniquenium/Uniquenium/blob/main/TODO.md" target="_blank" rel="noreferrer">TODO list</a> to see if it&#39;s already planned</li><li>Develop a plugin yourself (refer to <a href="/en/custom-developing/plugin">Plugin Development Guide</a>)</li><li>Submit a Feature Request Issue on GitHub with detailed requirements and use cases</li></ol><h2 id="data-backup" tabindex="-1">Data &amp; Backup <a class="header-anchor" href="#data-backup" aria-label="Permalink to &quot;Data &amp; Backup&quot;">​</a></h2><h3 id="q-where-are-configuration-files-and-data-stored" tabindex="-1">Q: Where are configuration files and data stored? <a class="header-anchor" href="#q-where-are-configuration-files-and-data-stored" aria-label="Permalink to &quot;Q: Where are configuration files and data stored?&quot;">​</a></h3><p><strong>A:</strong> User data is stored by default at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Windows: %APPDATA%\\Uniquenium\\</span></span>
<span class="line"><span>├── Pages\\         # Page configuration files</span></span>
<span class="line"><span>├── Plugins\\       # Installed plugins</span></span>
<span class="line"><span>├── Settings\\      # Program settings</span></span>
<span class="line"><span>├── Templates\\     # Exported templates</span></span>
<span class="line"><span>└── Logs\\          # Log files</span></span></code></pre></div><h3 id="q-how-to-backup-and-migrate-data" tabindex="-1">Q: How to backup and migrate data? <a class="header-anchor" href="#q-how-to-backup-and-migrate-data" aria-label="Permalink to &quot;Q: How to backup and migrate data?&quot;">​</a></h3><p><strong>A:</strong> Simply copy the entire <code>%APPDATA%\\Uniquenium\\</code> folder to the same location on the new computer. It is recommended to back up this folder regularly.</p><hr><p>Didn&#39;t find your question?</p><ul><li><a href="/en/">Read the official documentation</a></li><li><a href="https://github.com/Uniquenium/Uniquenium/issues" target="_blank" rel="noreferrer">Submit a GitHub Issue</a></li><li><a href="https://github.com/Uniquenium/Uniquenium/discussions" target="_blank" rel="noreferrer">Join the discussion</a></li></ul>`,80)]))}const g=t(n,[["render",s]]);export{c as __pageData,g as default};
